/**
 * @file
 *
 * Implementation of the multiple precision utilities.
 *
 * @ingroup bn
 */

#include <inttypes.h>

#include "relic_core.h"

/*============================================================================*/
/* Private definitions                                                        */
/*============================================================================*/

/**
 * Statistical distance 1/2^\lambda between sampling and uniform distribution.
 */
#define RAND_DIST               40

/*============================================================================*/
/* Public definitions                                                         */
/*============================================================================*/

void bn_copy(bn_t c, const bn_t a) {
        if (c->dp == a->dp) {
                return;
        }

        bn_grow(c, a->used);
        dv_copy(c->dp, a->dp, a->used);

        c->used = a->used;
        c->sign = a->sign;
}

void bn_abs(bn_t c, const bn_t a) {
        if (c->dp != a->dp) {
                bn_copy(c, a);
        }
        c->sign = RLC_POS;
}

void bn_neg(bn_t c, const bn_t a) {
        if (c->dp != a->dp) {
                bn_copy(c, a);
        }
        if (!bn_is_zero(c)) {
                c->sign = a->sign ^ 1;
        }
}

int bn_sign(const bn_t a) {
        return a->sign;
}

void bn_zero(bn_t a) {
        a->sign = RLC_POS;
        a->used = 1;
        dv_zero(a->dp, a->alloc);
}

int bn_is_zero(const bn_t a) {
        if (a->used == 0) {
                return 1;
        }
        if ((a->used == 1) && (a->dp[0] == 0)) {
                return 1;
        }
        return 0;
}

int bn_is_even(const bn_t a) {
        if (bn_is_zero(a)) {
                return 1;
        }
        if ((a->dp[0] & 0x01) == 0) {
                return 1;
        }
        return 0;
}

int bn_bits(const bn_t a) {
        int bits;

        if (bn_is_zero(a)) {
                return 0;
        }

        /* Bits in lower digits. */
        bits = (a->used - 1) * RLC_DIG;

        return bits + util_bits_dig(a->dp[a->used - 1]);
}

int bn_get_bit(const bn_t a, int bit) {
        int d;

        if (bit < 0) {
                RLC_THROW(ERR_NO_VALID);
                return 0;
        }

        if (bit > bn_bits(a)) {
                return 0;
        }

        RLC_RIP(bit, d, bit);

        if (d >= a->used) {
                return 0;
        } else {
                return (a->dp[d] >> bit) & (dig_t)1;
        }
}

void bn_set_bit(bn_t a, int bit, int value) {
        int d;

        if (bit < 0) {
                RLC_THROW(ERR_NO_VALID);
                return;
        }

        RLC_RIP(bit, d, bit);

        bn_grow(a, d);

        if (value == 1) {
                a->dp[d] |= ((dig_t)1 << bit);
                if ((d + 1) > a->used) {
                        a->used = d + 1;
                }
        } else {
                a->dp[d] &= ~((dig_t)1 << bit);
                bn_trim(a);
        }
}

int bn_ham(const bn_t a) {
        int c = 0;

        for (int i = 0; i < bn_bits(a); i++) {
                c += bn_get_bit(a, i);
        }

        return c;
}

void bn_get_dig(dig_t *c, const bn_t a) {
        *c = a->dp[0];
}

void bn_set_dig(bn_t a, dig_t digit) {
        bn_zero(a);
        a->dp[0] = digit;
        a->used = 1;
        a->sign = RLC_POS;
}

void bn_set_2b(bn_t a, int b) {
        int i, d;

        if (b < 0) {
                bn_zero(a);
        } else {
                RLC_RIP(b, d, b);

                bn_grow(a, d + 1);
                for (i = 0; i < d; i++) {
                        a->dp[i] = 0;
                }
                a->used = d + 1;
                a->dp[d] = ((dig_t)1 << b);
                a->sign = RLC_POS;
        }
}

void bn_rand(bn_t a, int sign, int bits) {
        int digits;

        RLC_RIP(bits, digits, bits);
        digits += (bits > 0 ? 1 : 0);

        bn_grow(a, digits);

        rand_bytes((uint8_t *)a->dp, digits * sizeof(dig_t));

        a->used = digits;
        a->sign = sign;
        if (bits > 0) {
                dig_t mask = ((dig_t)1 << (dig_t)bits) - 1;
                a->dp[a->used - 1] &= mask;
        }
        bn_trim(a);
}
